import { useState } from "react";

import { BookmarkIcon } from "@/components/ui/icons";

import { Button, ButtonSelectionIcon } from "@/components/ui/button";

function SelectedButtonDemo({ size = "default", variant = "tertiary", disabled = false }: {
    size?: "default" | "expressive" | "icon" | "icon-expressive";
    variant?: "secondary" | "tertiary";
    disabled?: boolean;
}) {
    const [selected, setSelected] = useState(true);
    const iconOnly = size === "icon" || size === "icon-expressive";
    return (<Button size={size} variant={variant} selected={selected} disabled={disabled} aria-label={iconOnly ? "Bookmark item" : undefined} onClick={() => setSelected(current => !current)}>
      <ButtonSelectionIcon><BookmarkIcon /></ButtonSelectionIcon>
      {iconOnly ? null : "Selected"}
    </Button>);
}

export const Demo = () => (<div className="flex flex-col gap-6">
        {(["default", "expressive"] as const).map((size) => (<div key={size} className="flex flex-wrap items-center gap-3">
            <Button size={size} variant="primary">Primary purple</Button>
            <Button size={size} variant="primary" primaryColor="pink">Primary pink</Button>
            <Button size={size} variant="secondary">Secondary</Button>
            <Button size={size}>Tertiary</Button>
            <Button size={size} variant="destructive">Destructive</Button>
            <SelectedButtonDemo size={size}/>
            <Button size={size} variant="ghost">Ghost</Button>
            <Button size={size} variant="link">Link</Button>
          </div>))}
      </div>);

function ResponseStreamingDemo() {
  const [text, setText] = useState(responseAnswers[0])
  const [streaming, setStreaming] = useState(false)
  const timerRef = useRef<number | null>(null)

  const clear = useCallback(() => {
    if (timerRef.current === null) return
    window.clearInterval(timerRef.current)
    timerRef.current = null
  }, [])

  useEffect(() => clear, [clear])

  function start() {
    clear()
    const words = responseAnswers[0].split(" ")
    let shown = 0
    setText("")
    setStreaming(true)
    timerRef.current = window.setInterval(() => {
      shown += 1
      setText(words.slice(0, shown).join(" "))
      if (shown < words.length) return
      clear()
      setStreaming(false)
    }, responseStreamStepMs)
  }

  function stop() {
    clear()
    setStreaming(false)
  }

  return (
    <div className="flex w-full max-w-(--response-max-width) flex-col gap-4">
      <Message align="start">
        <MessageContent>
          <MessageHeader>
            {streaming ? "Responding" : "Assistant"}
          </MessageHeader>
          <Bubble variant="ghost">
            <BubbleContent>
              <Response>
                <ResponseStream text={text} streaming={streaming} />
              </Response>
            </BubbleContent>
          </Bubble>
        </MessageContent>
      </Message>
      <div className="flex gap-2">
        <Button
          variant="secondary"
          size="default"
          onClick={start}
          disabled={streaming}
        >
          Stream response
        </Button>
        <Button
          variant="secondary"
          size="default"
          onClick={stop}
          disabled={!streaming}
        >
          Stop
        </Button>
      </div>
    </div>
  )
}
